"""ShellNavigation page object - generated by TestAutomationScriptGenerator from studio:REQ-01.

Every locator is a placeholder: replace each value marked "TODO: confirm selector" with the real
selector (prefer data-testid or role-based selectors). Keep raw selectors out of the tests.
"""

from iharmony.core.base_page import BasePage


class ShellNavigationPage(BasePage):
    """Page object for the shell navigation feature."""

    # Overview page region (shown when hash is empty or unknown)
    OVERVIEW_PAGE_REGION = "role=region[name='Overview']"
    # Get a quote page region
    GET_A_QUOTE_PAGE_REGION = "role=region[name='Get a quote']"
    # File a claim page region
    FILE_A_CLAIM_PAGE_REGION = "role=region[name='File a claim']"
    # Navigation link: Get a quote
    NAV_QUOTE_LINK = "[data-testid='nav-quote']"
    # Navigation link: File a claim
    NAV_CLAIM_LINK = "[data-testid='nav-claim']"
    # Navigation toggle button (mobile)
    NAV_TOGGLE_BUTTON = "button[aria-label='Open navigation']"
    # Brand link
    BRAND_LINK = "a[aria-label='Harbor Mutual Automation Lab home']"

    def open(self, base_url: str, path: str = "") -> None:
        """Open this page relative to the environment base URL."""
        self.navigate(base_url.rstrip("/") + path)

    def is_overview_page_visible(self) -> bool:
        return self.is_visible(self.OVERVIEW_PAGE_REGION)

    def is_get_a_quote_page_visible(self) -> bool:
        return self.is_visible(self.GET_A_QUOTE_PAGE_REGION)

    def is_file_a_claim_page_visible(self) -> bool:
        return self.is_visible(self.FILE_A_CLAIM_PAGE_REGION)

    def click_get_a_quote_link_in_the_left_navigation(self) -> None:
        self.click(self.NAV_QUOTE_LINK)

    def are_all_other_pages_hidden(self) -> bool:
        # Only Overview or Get a quote region should be visible, others hidden
        # For this test, check that File a claim is not visible
        return not self.is_file_a_claim_page_visible()

    def click_brand_link(self) -> None:
        self.click(self.BRAND_LINK)

    def set_viewport_width(self, width: int) -> None:
        # Playwright page object exposes set_viewport_size
        self.page.set_viewport_size({"width": width, "height": 800})

    def is_navigation_visible(self) -> bool:
        # Navigation is visible if the left nav is present
        # Use Get a quote nav link as proxy for nav visibility
        return self.has_any_visible(self.NAV_QUOTE_LINK)

    def is_nav_toggle_button_visible(self) -> bool:
        return self.is_visible(self.NAV_TOGGLE_BUTTON)

    def get_title(self) -> str:
        return super().get_title()
